function toothGeometry(a0,a1){
  const a=mouthRim(a0),b=mouthRim(a1);
  a.z+=0.017;b.z+=0.017;
  const h=0.067*(0.85+0.15*mouthOpening);
  const p=[
    a.x,a.y-0.008,a.z,b.x,b.y-0.008,b.z,
    b.x,b.y-h,b.z+0.008,a.x,a.y-h,a.z+0.008,
    a.x,a.y-0.008,a.z-0.045,b.x,b.y-0.008,b.z-0.045,
    b.x,b.y-h,b.z-0.037,a.x,a.y-h,a.z-0.037
